<?php declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/includes/auth.php';$db=db();$e=fn($v)=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');$s=$db->query("SELECT COUNT(*) invoices,COALESCE(SUM(CASE WHEN status<>'cancelled' THEN total ELSE 0 END),0) billed,COALESCE(SUM(amount_paid),0) collected,COALESCE(SUM(CASE WHEN status IN ('sent','partially_paid','overdue') THEN balance_due ELSE 0 END),0) outstanding,COALESCE(SUM(CASE WHEN status='overdue' THEN balance_due ELSE 0 END),0) overdue FROM invoices")->fetch();$ex=(float)$db->query("SELECT COALESCE(SUM(amount),0) FROM expenses WHERE status='recorded'")->fetchColumn();$projects=(int)$db->query('SELECT COUNT(*) FROM client_projects')->fetchColumn();$profit=(float)$s['collected']-$ex;?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Business Intelligence</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-4"><h1 class="h3">Business Intelligence</h1><div class="row g-3"><div class="col-md-4"><div class="card"><div class="card-body"><small>Revenue Billed</small><h2><?=number_format((float)$s['billed'],2)?></h2></div></div></div><div class="col-md-4"><div class="card"><div class="card-body"><small>Collected</small><h2><?=number_format((float)$s['collected'],2)?></h2></div></div></div><div class="col-md-4"><div class="card"><div class="card-body"><small>Estimated Net Cash Profit</small><h2><?=number_format($profit,2)?></h2></div></div></div><div class="col-md-3"><div class="card"><div class="card-body"><small>Outstanding</small><h3><?=number_format((float)$s['outstanding'],2)?></h3></div></div></div><div class="col-md-3"><div class="card"><div class="card-body"><small>Overdue</small><h3><?=number_format((float)$s['overdue'],2)?></h3></div></div></div><div class="col-md-3"><div class="card"><div class="card-body"><small>Invoices</small><h3><?=$e($s['invoices'])?></h3></div></div></div><div class="col-md-3"><div class="card"><div class="card-body"><small>Projects</small><h3><?=$e($projects)?></h3></div></div></div></div></main></body></html>